#include "unity.h"
#include "helpers.h"
#include "buffer.h" // Assuming buffer.h defines buffer_t and function prototypes
#include <string.h> // For memset, strlen

void setUp(void) { }
void tearDown(void) { }

/**
 * @brief Tests the buffer_fill function with a non-zero character.
 *
 * This test verifies that buffer_fill correctly sets all bytes
 * within the buffer's allocated data region to the specified character,
 * and that the buffer's length and size are as expected afterwards.
 */
void unit_test_buffer_fill_basic_char(void) {
    // Setup: Create a buffer with a specific size and a fill character
    size_t initial_size = 10;
    int fill_char = 'X';
    buffer_t *buf = helper_create_buffer_with_size(initial_size);

    // Assert initial state (buffer should be null-filled by calloc)
    TEST_ASSERT_NOT_NULL(buf);
    TEST_ASSERT_EQUAL_INT(0, buffer_length(buf)); // Initially empty string
    TEST_ASSERT_EQUAL_INT(initial_size, buffer_size(buf));
    TEST_ASSERT_EQUAL_STRING("", buf->data);

    // Test: Call buffer_fill to fill the buffer with 'X'
    buffer_fill(buf, fill_char);

    // Assertions: Verify the buffer's content, length, and size
    // Create an expected string for comparison
    char expected_data[initial_size + 1];
    memset(expected_data, fill_char, initial_size);
    expected_data[initial_size] = '\0'; // Null-terminate the expected string

    TEST_ASSERT_EQUAL_STRING(expected_data, buf->data);
    TEST_ASSERT_EQUAL_INT(initial_size, buffer_length(buf)); // Length should now be the full size
    TEST_ASSERT_EQUAL_INT(initial_size, buffer_size(buf));   // Size should remain unchanged

    // Cleanup: Free the allocated buffer
    buffer_free(buf);
}

/**
 * @brief Tests the buffer_fill function with a null character (0).
 *
 * This test verifies that buffer_fill correctly clears the buffer
 * when filled with a null character, effectively making it an empty string.
 */
void unit_test_buffer_fill_with_null_char(void) {
    // Setup: Create a buffer with some initial data
    const char *initial_str = "hello";
    size_t initial_size = strlen(initial_str) + 5; // Make it larger than initial_str
    buffer_t *buf = helper_create_buffer_from_string(initial_str);

    // Resize to a larger size to ensure buffer_fill operates on the full allocated size
    // and not just the string length.
    // buffer_new_with_copy creates a buffer of strlen(str), so we need to resize.
    // Or, simpler, just create with size and then put data.
    buffer_t *buf_to_clear = helper_create_buffer_with_size(initial_size);
    TEST_ASSERT_NOT_NULL(buf_to_clear);
    strcpy(buf_to_clear->data, initial_str); // Put some data in it

    TEST_ASSERT_EQUAL_STRING(initial_str, buf_to_clear->data);
    TEST_ASSERT_EQUAL_INT(strlen(initial_str), buffer_length(buf_to_clear));
    TEST_ASSERT_EQUAL_INT(initial_size, buffer_size(buf_to_clear));

    // Test: Call buffer_fill to clear the buffer with 0
    buffer_fill(buf_to_clear, 0);

    // Assertions: Verify the buffer's content, length, and size
    TEST_ASSERT_EQUAL_STRING("", buf_to_clear->data); // Should be an empty string
    TEST_ASSERT_EQUAL_INT(0, buffer_length(buf_to_clear)); // Length should be 0
    TEST_ASSERT_EQUAL_INT(initial_size, buffer_size(buf_to_clear)); // Size should remain unchanged

    // Cleanup: Free the allocated buffer
    buffer_free(buf_to_clear);
    buffer_free(buf); // Free the unused buffer from initial setup
}


int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_fill_basic_char);
    RUN_TEST(unit_test_buffer_fill_with_null_char);
    return UNITY_END();
}

