buffer_t *helper_create_buffer_from_string(const char *str) {
  return buffer_new_with_copy((char *)str);
}

// Creates a new buffer_t with a specified size.

buffer_t *helper_create_buffer_with_size(size_t n) {
  return buffer_new_with_size(n);
}


